const inputData = $('Execute Workflow Trigger').first()?.json || {};
const fechaCorteStr = inputData.fecha_corte || '2026-10-31 23:59:59-06';
const fechaCorteMs = new Date(fechaCorteStr).getTime();

const inventarios = $('Obtener Inventario').all().map(i => i.json);
const declaraciones = $('Obtener Declaraciones').all().map(i => i.json);
const importadores = $('Obtener Importadores').all().map(i => i.json);

const impMap = new Map(importadores.map(imp => [imp.id_importador, imp.razon_social]));
const decMap = new Map(declaraciones.map(d => [d.id_declaracion, d]));

const stockPorDua = new Map();
for (const inv of inventarios) {
  if (Number(inv.cantidad_almacenada) <= 0 || inv.fecha_salida) continue;
  const idDec = inv.id_declaracion;
  if (!stockPorDua.has(idDec)) {
    stockPorDua.set(idDec, { totalCantidad: 0, bodegas: new Set() });
  }
  const item = stockPorDua.get(idDec);
  item.totalCantidad += Number(inv.cantidad_almacenada);
  item.bodegas.add(inv.id_bodega);
}

const resultados = [];
for (const [idDec, infoStock] of stockPorDua.entries()) {
  const d = decMap.get(idDec);
  if (!d) continue;

  const ingresoMs = new Date(d.fecha_ingreso_recinto).getTime();
  const diasPermanencia = Math.round(((fechaCorteMs - ingresoMs) / (1000 * 60 * 60 * 24)) * 100) / 100;

  resultados.push({
    numero_dua: d.numero_dua,
    regimen: d.regimen,
    estado_declaracion: d.estado,
    importador: impMap.get(d.id_importador) || 'Desconocido',
    fecha_ingreso_recinto: d.fecha_ingreso_recinto,
    fecha_corte_evaluacion: fechaCorteStr,
    dias_permanencia_recinto: diasPermanencia,
    cantidad_total_almacenada: Math.round(infoStock.totalCantidad * 100) / 100,
    bodegas_involucradas: infoStock.bodegas.size
  });
}

resultados.sort((a, b) => b.dias_permanencia_recinto - a.dias_permanencia_recinto || a.numero_dua.localeCompare(b.numero_dua));

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_permanencia_en_bodega',
    filtros: { fecha_corte: fechaCorteStr, stock_activo: true },
    total_registros: resultados.length,
    es_parcial: false,
    datos: resultados
  }
}];
